import math

def area_of_polygon_inside_circle(circle_radius, number_of_sides):
    n = number_of_sides
    r = circle_radius
    if n < 3:
        raise ValueError("Number of sides must be at least 3")

    angle = 2 * math.pi / n
    area = (n * r**2 * math.sin(angle)) / 2
    return round(area, 3)

