def throughput_vowel_shift(text, n):
    if text in (None, ''):
        return text

    vowels = [c for c in text if c in 'aeiouAEIOU']
    if not vowels:
        return text

    n = n % len(vowels)
    if n < 0:
        n += len(vowels)

    shifted_vowels = vowels[-n:] + vowels[:-n]
    vowel_index = 0

    result = []
