def throughput_mul_power(n, k):
    from math import gcd
    # Dictionary to store prime factors and their counts
    factors = {}
    temp_n = n
    d = 2
    while d * d <= temp_n:
        while temp_n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp_n //= d
        d += 1
    if temp_n > 1:
        factors[temp_n] = factors.get(temp_n, 0) + 1

