    # Find the prime factorization of n
    factors = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        factors[n] = 1

    # Calculate the required multiplier to make n * x = k^m
    # We need to find the smallest x such that n * x is a perfect k-th power.
    # This means for every prime p in n, the exponent of p in (n * x) must be a multiple of k.
    # Let v_p(n) be the exponent of p in n. We need v_p(n) + v_p(x) ≡ 0 (mod k).
    # So v_p(x) ≡ -v_p(n) (mod k). The smallest non-negative v_p(x) is (k - v_p(n) % k) % k.
