def scaling_numRollsToTarget(d, f, target):
    if target < d or target > d * f:
        return 0

    # Use inclusion-exclusion principle
    # We want coefficient of x^target in (x + x^2 + ... + x^f)^d
    # This equals coefficient of x^(target-d) in (1 + x + ... + x^(f-1))^d
    # Which is sum_{j=0 to d} (-1)^j * C(d, j) * C(target - d - j*f + d - 1, d - 1)
